package com.mouseoveroptions;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class MouseoverOptionsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(MouseoverOptionsPlugin.class);
		RuneLite.main(args);
	}
}

package com.mouseoveroptions;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("mouseoveroptions")
public interface MouseoverOptionsConfig extends Config
{
    @ConfigItem(
            keyName = "minimumOptions",
            name = "Minimum extra options",
            description = "The badge is only shown once at least this many extra options are available.",
            position = 1
    )
    default int minimumOptions()
    {
        return 1;
    }

    @ConfigItem(
            keyName = "includeExamine",
            name = "Count Examine",
            description = "Whether the 'Examine' entry counts towards the extra options total.",
            position = 2
    )
    default boolean includeExamine()
    {
        return true;
    }

    @ConfigItem(
            keyName = "showOnWidgets",
            name = "Show on interface widgets",
            description = "Show the badge while hovering interface widgets (bank, inventory, shops, etc), "
                    + "not just objects/NPCs/ground items in the game world.",
            position = 3
    )
    default boolean showOnWidgets()
    {
        return true;
    }

    @ConfigItem(
            keyName = "textColor",
            name = "Text color",
            description = "Color used for the '+N options' text.",
            position = 4
    )
    default Color textColor()
    {
        return Color.WHITE;
    }
}

package com.mouseoveroptions;

import java.awt.*;
import java.util.Arrays;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;

import com.google.common.base.Strings;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.mousehighlight.MouseHighlightConfig;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.Text;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import lombok.extern.slf4j.Slf4j;

/**
 * Adds a small "+N options" tooltip underneath the vanilla mouseover tooltip
 * whenever there are more right-click options available at the cursor than
 * the single option/name the tooltip already shows.
 * <p>
 * RuneLite draws every {@link Tooltip} added to the {@link TooltipManager}
 * in the same frame stacked vertically near the cursor, so adding our own
 * extra tooltip here is enough to have it appear directly below the one the
 * built-in "Mouse Highlight" plugin produces - no need to touch core code.
 */
@Slf4j
public class MouseoverOptionsOverlay extends Overlay
{
    private final Client client;
    private final TooltipManager tooltipManager;
    private final MouseoverOptionsConfig config;
    private final MouseHighlightConfig highlightConfig;

    // Mirrors the vanilla client's own exclusion list for the
    // "<action> / N more options" counter.
    private static final Set<String> ALWAYS_IGNORED_OPTIONS = new HashSet<>(Arrays.asList(
            "walk here",
            "cancel",
            "continue",
            "move"
    ));

    /**
     * Menu types which are on widgets.
     */
    private static final Set<MenuAction> WIDGET_MENU_ACTIONS = EnumSet.of(
            MenuAction.WIDGET_TYPE_1,
            MenuAction.WIDGET_TARGET,
            MenuAction.WIDGET_CLOSE,
            MenuAction.WIDGET_TYPE_4,
            MenuAction.WIDGET_TYPE_5,
            MenuAction.WIDGET_CONTINUE,
            MenuAction.ITEM_USE_ON_ITEM,
            MenuAction.WIDGET_USE_ON_ITEM,
            MenuAction.ITEM_FIRST_OPTION,
            MenuAction.ITEM_SECOND_OPTION,
            MenuAction.ITEM_THIRD_OPTION,
            MenuAction.ITEM_FOURTH_OPTION,
            MenuAction.ITEM_FIFTH_OPTION,
            MenuAction.ITEM_USE,
            MenuAction.WIDGET_FIRST_OPTION,
            MenuAction.WIDGET_SECOND_OPTION,
            MenuAction.WIDGET_THIRD_OPTION,
            MenuAction.WIDGET_FOURTH_OPTION,
            MenuAction.WIDGET_FIFTH_OPTION,
            MenuAction.EXAMINE_ITEM,
            MenuAction.WIDGET_TARGET_ON_WIDGET,
            MenuAction.CC_OP_LOW_PRIORITY,
            MenuAction.CC_OP
    );


    /**
     * Menu actions that never represent a "real" extra option and should
     * never be counted, regardless of configuration.
     */
    private static final Set<MenuAction> ALWAYS_IGNORED_ACTIONS = EnumSet.of(
            MenuAction.WALK,
            MenuAction.CANCEL,
            MenuAction.RUNELITE,
            MenuAction.RUNELITE_OVERLAY,
            MenuAction.RUNELITE_OVERLAY_CONFIG
    );

    @Inject
    private MouseoverOptionsOverlay(Client client, TooltipManager tooltipManager, MouseoverOptionsConfig config, ConfigManager configManager)
    {
        this.client = client;
        this.tooltipManager = tooltipManager;
        this.config = config;
        this.highlightConfig = configManager.getConfig(MouseHighlightConfig.class);
        setPosition(OverlayPosition.TOOLTIP);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    /**
     * Indicates whether the highlight should be shown for the given menu entry.
     * sourced from: main/java/net/runelite/client/plugins/mousehighlight/MouseHighlightOverlay.java
     * @param menuEntry The menu entry to check.
     * @return True if the highlight should be shown for this menu entry, false otherwise.
     */
    private boolean isHighlightShown(MenuEntry menuEntry)
    {
        String target = menuEntry.getTarget();
        String option = menuEntry.getOption();
        MenuAction type = menuEntry.getType();

        if (type == MenuAction.RUNELITE_OVERLAY || type == MenuAction.CC_OP_LOW_PRIORITY)
        {
            // These are always right click only
            return false;
        }

        if (Strings.isNullOrEmpty(option))
        {
            return false;
        }

        // Trivial options that don't need to be highlighted, add more as they appear.
        switch (option)
        {
            case "Walk here":
            case "Cancel":
            case "Continue":
            case "Set heading":
                return false;
            case "Move":
                // Hide overlay on sliding puzzle boxes
                if (target.contains("Sliding piece"))
                {
                    return false;
                }
        }

        if (WIDGET_MENU_ACTIONS.contains(type))
        {
            final int widgetId = menuEntry.getParam1();
            final int groupId = WidgetUtil.componentToInterface(widgetId);

            if (!highlightConfig.uiTooltip())
            {
                return false;
            }

            if (!highlightConfig.chatboxTooltip() && groupId == InterfaceID.CHATBOX)
            {
                return false;
            }

            if (highlightConfig.disableSpellbooktooltip() && groupId == InterfaceID.MAGIC_SPELLBOOK)
            {
                return false;
            }
        }

        // If this varc is set, a tooltip will be displayed soon
        int tooltipTimeout = client.getVarcIntValue(VarClientID.TOOLTIP_TIME);
        if (tooltipTimeout > client.getGameCycle())
        {
            return false;
        }

        // If this varc is set, a tooltip is already being displayed
        int tooltipDisplayed = client.getVarcIntValue(VarClientID.TOOLTIP_BUILT);
        if (tooltipDisplayed == 1)
        {
            return false;
        }

        return true;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        // Don't show the badge while the real right-click menu is open.
        if (client.isMenuOpen())
        {
            return null;
        }

        MenuEntry[] menuEntries = client.getMenu().getMenuEntries();
        int last = menuEntries.length - 1;

        if (last < 0)
        {
            return null;
        }

        // Last item is the top priority
        MenuEntry primaryEntry = menuEntries[last];

        // Don't show the +options if the highlight is not shown
        if (!isHighlightShown(primaryEntry))
        {
            return null;
        }

        int realOptions = 0;

        for (MenuEntry entry : menuEntries)
        {
            if (isIgnored(entry))
            {
                continue;
            }

            realOptions++;
        }

        log.debug("All options: [{}] filtered: [{}]", menuEntries.length, realOptions);

        if (realOptions < Math.max(1, config.minimumOptions()))
        {
            return null;
        }

        // Construct the primary text for the tooltip based on the menu entry's option and target
        String target = primaryEntry.getTarget();
        String option = primaryEntry.getOption();
        String primaryText = option + (Strings.isNullOrEmpty(target) ? "" : " " + target);

        // Add tooltip
        String label = "+" + realOptions + (realOptions == 1 ? " option" : " options");
        tooltipManager.add(new Tooltip(new ScaledOptionsBadge(primaryText, label, config.textColor(), 0.75f)));

        return null;
    }

    private boolean isIgnored(MenuEntry entry)
    {
        if (ALWAYS_IGNORED_ACTIONS.contains(entry.getType()))
        {
            return true;
        }

        String option = entry.getOption();
        if (option == null || option.isEmpty() || ALWAYS_IGNORED_OPTIONS.contains(option.toLowerCase()))
        {
            return true;
        }

        // These two are now opt-in deviations from the native count, not
        // defaults - flip the config defaults to false if you want strict
        // parity with "Show mouseover text".
        if (!config.showOnWidgets() && entry.getWidget() != null)
        {
            return true;
        }
        if (!config.includeExamine() && isExamine(entry.getType()))
        {
            return true;
        }

        return false;
    }

    private boolean isExamine(MenuAction type)
    {
        switch (type)
        {
            case EXAMINE_OBJECT:
            case EXAMINE_NPC:
            case EXAMINE_ITEM_GROUND:
            case EXAMINE_WORLD_ENTITY:
                return true;
            default:
                return false;
        }
    }

    private static class ScaledOptionsBadge implements LayoutableRenderableEntity
    {
        private static final int PADDING = 1;

        private final String primaryText;
        private final String text;
        private final Color textColor;
        private final float fontScale;
        private Point location = new Point(0, 0);
        private Rectangle bounds = new Rectangle();

        private ScaledOptionsBadge(String primaryText, String text, Color textColor, float fontScale)
        {
            this.primaryText = Text.removeTags(primaryText);
            this.text = text;
            this.textColor = textColor;
            this.fontScale = fontScale;
        }

        @Override
        public Dimension render(Graphics2D graphics)
        {
            Font base = graphics.getFont();
            Font scaled = base.deriveFont(base.getSize2D() * fontScale);
            graphics.setFont(scaled);
            FontMetrics metrics = graphics.getFontMetrics();

            // Calculated width of the primary menu item
            Font primaryFont = FontManager.getRunescapeSmallFont();
            int primaryWidth = graphics.getFontMetrics(primaryFont).stringWidth(primaryText) + 2 * ComponentConstants.STANDARD_BORDER - 1;

            int width = metrics.stringWidth(text) + 2 * PADDING;
            int height = metrics.getHeight() + 2 * PADDING;

            Color backgroundColor = ComponentConstants.STANDARD_BACKGROUND_COLOR;
            final int BORDER_OFFSET = ComponentConstants.STANDARD_BORDER / 2;
            final float COLOR_OFFSET = 0.2f;
            final float OUTER_COLOR_OFFSET = 1 - COLOR_OFFSET;
            final float INNER_COLOR_OFFSET = 1 + COLOR_OFFSET;
            final float ALPHA_COLOR_OFFSET = 1 + 2 * COLOR_OFFSET;

            // Right-align the badge under the cursor position TooltipOverlay gave us.
            int x = location.x + Math.max(primaryWidth - width, 0);
            int y = location.y - BORDER_OFFSET;

            // Create the fill
            graphics.setColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
            graphics.fillRect(x, y, width, height);

            // Replicate the color mixing
            // source: main/java/net/runelite/client/ui/overlay/components/BackgroundComponent.java
            Color outsideStrokeColor = new Color(
                    (int) (backgroundColor.getRed() * OUTER_COLOR_OFFSET),
                    (int) (backgroundColor.getGreen() * OUTER_COLOR_OFFSET),
                    (int) (backgroundColor.getBlue() * OUTER_COLOR_OFFSET),
                    Math.min(255, (int) (backgroundColor.getAlpha() * ALPHA_COLOR_OFFSET))
            );

            Color insideStrokeColor = new Color(
                    Math.min(255, (int) (backgroundColor.getRed() * INNER_COLOR_OFFSET)),
                    Math.min(255, (int) (backgroundColor.getGreen() * INNER_COLOR_OFFSET)),
                    Math.min(255, (int) (backgroundColor.getBlue() * INNER_COLOR_OFFSET)),
                    Math.min(255, (int) (backgroundColor.getAlpha() * ALPHA_COLOR_OFFSET))
            );

            // Render outside stroke
            final Rectangle outsideStroke = new Rectangle();
            outsideStroke.setLocation(x, y);
            outsideStroke.setSize(width - BORDER_OFFSET / 2, height - BORDER_OFFSET / 2);
            graphics.setColor(outsideStrokeColor);
            graphics.draw(outsideStroke);

            // Render inside stroke
            final Rectangle insideStroke = new Rectangle();
            insideStroke.setLocation(x + BORDER_OFFSET / 2, y + BORDER_OFFSET / 2);
            insideStroke.setSize(width - BORDER_OFFSET - BORDER_OFFSET / 2, height - BORDER_OFFSET - BORDER_OFFSET / 2);
            graphics.setColor(insideStrokeColor);
            graphics.draw(insideStroke);

            // Render the text
            graphics.setColor(textColor);
            graphics.drawString(text, x + PADDING, y + metrics.getHeight() - PADDING / 2);

            bounds = new Rectangle(x, y, width, height);
            return bounds.getSize();
        }

        @Override
        public Rectangle getBounds()
        {
            return bounds;
        }

        @Override
        public void setPreferredLocation(Point position)
        {
            this.location = position;
        }

        @Override
        public void setPreferredSize(Dimension dimension)
        {
            // size is derived from the scaled font, not overridable here
        }
    }
}

package com.mouseoveroptions;

import javax.inject.Inject;
import com.google.inject.Provides;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Adds back the "+N options" badge that the Steam / Enhanced OSRS client shows
 * underneath the mouseover (hover) tooltip, indicating how many extra
 * right-click options are available besides the one shown in the tooltip.
 *
 * RuneLite's vanilla "Mouse Highlight" plugin only shows the name/target of the
 * top menu entry (e.g. "Net Fishing spot") but drops the little counter badge
 * that used to sit underneath it. This plugin restores that counter as its own
 * lightweight tooltip, stacked below the existing one by RuneLite's tooltip
 * renderer.
 */
@PluginDescriptor(
		name = "Mouseover Options+",
		description = "Shows a '+N options' badge under the hover tooltip, like the old Steam/Enhanced client, "
				+ "indicating how many extra right-click options are available",
		tags = {"tooltip", "menu", "options", "mouseover", "hover", "steam", "enhanced"}
)
public class MouseoverOptionsPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MouseoverOptionsOverlay overlay;

	@Provides
	MouseoverOptionsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MouseoverOptionsConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
	}
}
